<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';requireRole('admin');$base='..';$assetBase='../assets';$pageTitle='Data Mahasiswa';require __DIR__.'/../partials/head.php'; ?><div class="dashboard-layout"><?php require __DIR__.'/../partials/sidebar.php'; ?><main class="main"><div class="mobile-head"><b>Sistem Absensi QR</b><button class="menu-toggle">☰</button></div><header class="topbar"><div><h1>Data Mahasiswa</h1><p>Tambah, lihat, dan kelola identitas mahasiswa.</p></div><div class="top-actions"><a class="btn btn-ghost" href="../index.php">↗ Beranda</a></div></header>
<?php $msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&checkCsrf($_POST['csrf']??null)){$npm=trim($_POST['npm']);$nama=trim($_POST['nama']);$qr='MHS-'.$npm;$st=$pdo->prepare('INSERT INTO mahasiswa(npm,nama,jenis_kelamin,fakultas,prodi,angkatan,kelas_id,email,qr_code) VALUES(?,?,?,?,?,?,?, ?,?)');$st->execute([$npm,$nama,$_POST['jenis_kelamin'],'Teknik',trim($_POST['prodi']),2024,(int)$_POST['kelas_id'],$npm.'@student.unigha.ac.id',$qr]);$st=$pdo->prepare('INSERT INTO users(username,password,role) VALUES(?,?,"mahasiswa")');$st->execute([$npm,password_hash('123456',PASSWORD_DEFAULT)]);$msg='Mahasiswa ditambahkan. Password awal: 123456';}$classes=$pdo->query('SELECT * FROM kelas ORDER BY nama_kelas')->fetchAll();$rows=$pdo->query('SELECT m.*,k.nama_kelas FROM mahasiswa m LEFT JOIN kelas k ON k.id=m.kelas_id ORDER BY m.id DESC')->fetchAll();?><section class="section"><div class="section-head"><h2>Tambah mahasiswa</h2></div><?php if($msg):?><div class="notice success"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><div class="form-grid"><input class="input" name="npm" placeholder="NPM" required><input class="input" name="nama" placeholder="Nama lengkap" required><select class="select" name="jenis_kelamin"><option>Perempuan</option><option>Laki-laki</option></select><input class="input" name="prodi" value="Teknik Informatika"><select class="select" name="kelas_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['nama_kelas'])?></option><?php endforeach;?></select></div><div class="actions"><button class="btn btn-primary">Simpan mahasiswa</button></div></form></section><section class="section" style="margin-top:20px"><div class="table-wrap"><table class="table"><thead><tr><th>NPM</th><th>Nama</th><th>Prodi</th><th>Kelas</th><th>QR</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['npm'])?></td><td><?=e($r['nama'])?></td><td><?=e($r['prodi'])?></td><td><?=e($r['nama_kelas']??'-')?></td><td><?=e($r['qr_code'])?></td></tr><?php endforeach;?></tbody></table></div></section>
</main></div><?php require __DIR__.'/../partials/footer.php'; ?>